<?php
namespace App\Http\Controllers;
use App\Models\{Guest,RoomType,Room,Reservation,MenuItem,RestaurantOrder,OrderItem,FolioCharge,Payment,User,AuditEntry,Setting};
use App\Services\HotelService as Hotel;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
class OperationsController extends Controller {
 private function owner(Request $q,Reservation $r):void {abort_unless($q->user()->active && ($q->user()->role!=='guest' || $q->user()->guest_id===$r->guest_id),403);}
 public function catalog(){return ['types'=>RoomType::orderBy('rate')->get(),'rooms'=>auth()->check()&&in_array(auth()->user()->role,['admin','frontdesk','housekeeping'])?Room::with('type')->get():[],'menu'=>MenuItem::where('available',true)->get(),'training_policy'=>app(RecommendationsController::class)->publicPolicy(),'policies'=>['checkIn'=>'14:00','checkOut'=>'12:00','freeCancellationHours'=>48,'lateCancellationPercent'=>50]];}
 public function availability(Request $q){$v=$q->validate(['arrival'=>'required|date|after_or_equal:today','departure'=>'required|date|after:arrival','guests'=>'required|integer|min:1|max:20']);return Room::with('type')->where('out_of_service',false)->whereHas('type',fn($t)=>$t->where('capacity','>=',$v['guests']))->whereNotIn('id',Reservation::whereNotIn('status',['Cancelled','Checked-out'])->where('arrival','<',$v['departure'])->where('departure','>',$v['arrival'])->select('room_id'))->get();}
 public function reservations(Request $q){$b=Reservation::with('guest','room.type','type','occupants')->orderByDesc('id');if($q->user()->role==='guest')$b->where('guest_id',$q->user()->guest_id);if($q->user()->role==='restaurant')return $b->where('status','Checked-in')->get()->map(fn($r)=>['id'=>$r->id,'code'=>$r->code,'guest'=>['name'=>$r->guest->name],'room'=>$r->room?->only('number'),'status'=>$r->status]);return $b->get();}
 public function book(Request $q){$v=$q->validate(['room_id'=>'required|exists:rooms,id','arrival'=>'required|date|after_or_equal:today','departure'=>'required|date|after:arrival','guest_count'=>'required|integer|min:1|max:20','guest_id'=>'sometimes|exists:guests,id','payer_guest_id'=>'sometimes|exists:guests,id','occupant_ids'=>'sometimes|array|min:1','occupant_ids.*'=>'exists:guests,id','requests'=>'nullable|string|max:2000','pay_with_points'=>'sometimes|boolean']);$staff=$q->user()->role!=='guest';if($staff && empty($v['guest_id']))Hotel::fail('Select a booking contact.');return response()->json(Hotel::book($v,$staff?$v['guest_id']:$q->user()->guest_id,$staff),201);}
 public function folio(Request $q,Reservation $reservation){$this->owner($q,$reservation);return Hotel::folio($reservation);}
 public function checkin(Reservation $reservation){return Hotel::checkIn($reservation);}
 public function checkout(Reservation $reservation){return Hotel::checkout($reservation);}
 public function changeDates(Request $q,Reservation $reservation){$this->owner($q,$reservation);$v=$q->validate(['arrival'=>'required|date|after_or_equal:today','departure'=>'required|date|after:arrival']);return DB::transaction(function()use($reservation,$v){$r=Reservation::lockForUpdate()->findOrFail($reservation->id);if($r->status!=='Confirmed'||$r->arrival<=today()->toDateString())Hotel::fail('Date changes require a confirmed future arrival.');if($r->points_redeemed)Hotel::fail('Points reservations require cancellation and a new eligible booking to change dates.');$room=Room::with('type')->lockForUpdate()->findOrFail($r->room_id);if($room->out_of_service||Reservation::where('room_id',$room->id)->where('id','!=',$r->id)->whereNotIn('status',['Cancelled','Checked-out'])->where('arrival','<',$v['departure'])->where('departure','>',$v['arrival'])->exists())Hotel::fail('Room is unavailable.');$oldNights=\Carbon\Carbon::parse($r->arrival)->diffInDays(\Carbon\Carbon::parse($r->departure));$newNights=\Carbon\Carbon::parse($v['arrival'])->diffInDays(\Carbon\Carbon::parse($v['departure']));$r->update([...$v,'amount'=>round($r->amount/$oldNights*$newNights,2)]);Hotel::audit('reservation.dates-changed',$r->code);return $r;});}
 public function cancel(Request $q,Reservation $reservation){$this->owner($q,$reservation);return DB::transaction(function()use($reservation){\App\Services\BusinessDate::assertNoCheckout($reservation->id);$r=Reservation::lockForUpdate()->findOrFail($reservation->id);if($r->status!=='Confirmed'||now()->gte(\Carbon\Carbon::parse($r->arrival.' 14:00')))Hotel::fail('Only a pre-arrival confirmed reservation may be cancelled.');$fee=now()->diffInHours(\Carbon\Carbon::parse($r->arrival.' 14:00'),false)>=48?0:round($r->amount*.5,2);$early=now()->diffInHours(\Carbon\Carbon::parse($r->arrival.' 14:00'),false)>=48;if($r->points_redeemed){$pointsRefund=$early?$r->points_redeemed:(int)floor($r->points_redeemed*.5);User::where('guest_id',$r->guest_id)->increment('points',$pointsRefund);}$r->update(['status'=>'Cancelled','amount'=>$fee,'pricing'=>null]);Hotel::audit('reservation.cancelled',$r->code,['fee'=>$fee]);return Hotel::folio($r);});}
 public function pay(Request $q,Reservation $reservation){$this->owner($q,$reservation);\App\Services\BusinessDate::assertOpen('Hotel');\App\Services\BusinessDate::assertNoCheckout($reservation->id);$v=$q->validate(['posting_location'=>'required|string|max:100','amount'=>'required|numeric|min:0.01|max:9999999','method'=>'required|in:Cash','idempotency_key'=>'required|uuid']);return DB::transaction(function()use($q,$reservation,$v){$r=Reservation::lockForUpdate()->findOrFail($reservation->id);$existing=Payment::where('idempotency_key',$v['idempotency_key'])->first();if($existing){abort_unless($existing->reservation_id===$r->id && (float)$existing->amount===round((float)$v['amount'],2)&&$existing->method===$v['method'],409);return $existing;}if($r->status==='Checked-out')Hotel::fail('Stay is closed.');$bal=Hotel::folio($r)['balance'];if($v['amount']>$bal+.005)Hotel::fail('Payment exceeds the remaining balance.');if($q->user()->role==='guest' && ($r->status!=='Confirmed'||$v['method']==='Cash'))Hotel::fail('Guests may make simulated pre-arrival payments only.');$p=Payment::create([...$v,'reservation_id'=>$r->id,'receipt'=>'RCPT-'.strtoupper(bin2hex(random_bytes(6))),'created_by'=>$q->user()->id]);Hotel::audit('payment.recorded',$p->receipt,['posted_by'=>$q->user()->id,'location'=>$v['posting_location'],'amount'=>$v['amount']]);return $p;});}
 public function refund(Request $q,Reservation $reservation){\App\Services\BusinessDate::assertOpen('Hotel');\App\Services\BusinessDate::assertNoCheckout($reservation->id);$v=$q->validate(['amount'=>'required|numeric|min:0.01','reason'=>'required|string|max:500','idempotency_key'=>'required|uuid']);return DB::transaction(function()use($q,$reservation,$v){$r=Reservation::lockForUpdate()->findOrFail($reservation->id);$old=Payment::where('idempotency_key',$v['idempotency_key'])->first();if($old){abort_unless($old->reservation_id===$r->id&&$old->kind==='Refund'&&(float)$old->amount===round((float)$v['amount'],2),409);return $old;}$bal=Hotel::folio($r)['balance'];if($bal>=0||$v['amount']>-$bal+.005)Hotel::fail('Refund exceeds the recorded credit balance.');$p=Payment::create(['reservation_id'=>$r->id,'amount'=>$v['amount'],'method'=>'Cash','kind'=>'Refund','idempotency_key'=>$v['idempotency_key'],'created_by'=>$q->user()->id,'receipt'=>'REF-'.strtoupper(bin2hex(random_bytes(6)))]);Hotel::audit('payment.refunded',$p->receipt,['reason'=>$v['reason']]);return $p;});}
 public function orders(){return RestaurantOrder::with('items','reservation.guest')->orderByDesc('id')->get();}
 public function order(Request $q){\App\Services\BusinessDate::assertOpen('Restaurant');$v=$q->validate(['discount_category'=>'sometimes|in:None,Senior,PWD','discount_verification'=>'nullable|string|max:500','channel'=>'sometimes|in:Dine-in,Room service','dining_table_id'=>'nullable|exists:dining_tables,id','delivery_reservation_id'=>'nullable|exists:reservations,id','table_label'=>'nullable|string|max:60','items'=>'required|array|min:1|max:50','items.*.menu_item_id'=>'required|exists:menu_items,id','items.*.quantity'=>'required|integer|min:1|max:100']);return DB::transaction(function()use($q,$v){$table=null;if(!empty($v['dining_table_id'])){$table=\App\Models\DiningTable::lockForUpdate()->findOrFail($v['dining_table_id']);if($table->status!=='Available')Hotel::fail('Table is not available.');}if(($v['channel']??'Dine-in')==='Room service'){if(empty($v['delivery_reservation_id'])||Reservation::find($v['delivery_reservation_id'])->status!=='Checked-in')Hotel::fail('Room service requires an active guest stay.');if($table)Hotel::fail('Room service does not use a dining table.');}$lines=[];$total=0;foreach($v['items'] as $item){$m=MenuItem::lockForUpdate()->findOrFail($item['menu_item_id']);if(!$m->available)Hotel::fail('A selected menu item is unavailable.');$lines[]=['menu_item_id'=>$m->id,'name'=>$m->name,'quantity'=>$item['quantity'],'unit_price'=>$m->price];$total+=$m->price*$item['quantity'];}$pricing=\App\Services\TrainingPolicy::restaurantPrice(round($total,2),$v['discount_category']??'None',$v['discount_verification']??null);$o=RestaurantOrder::create(['pricing'=>$pricing,'discount_category'=>$v['discount_category']??'None','discount_verification'=>$v['discount_verification']??null,'code'=>'ORD-'.strtoupper(bin2hex(random_bytes(5))),'table_label'=>$table?->label??($v['table_label']??null),'dining_table_id'=>$table?->id,'channel'=>$v['channel']??'Dine-in','delivery_reservation_id'=>$v['delivery_reservation_id']??null,'amount'=>$pricing['total'],'created_by'=>$q->user()->id]);$o->items()->createMany($lines);$table?->update(['status'=>'Occupied']);Hotel::audit('order.created',$o->code);return $o->load('items');});}
 public function settle(Request $q,RestaurantOrder $order){\App\Services\BusinessDate::assertNoOrderCheckout($order->id);\App\Services\BusinessDate::assertOpen('Restaurant');$v=$q->validate(['settlement'=>'required|in:Cash,Room','reservation_id'=>'required_if:settlement,Room|nullable|exists:reservations,id','cash_received'=>'required_if:settlement,Cash|nullable|numeric|min:0','idempotency_key'=>'required|uuid']);return DB::transaction(function()use($q,$order,$v){$r=isset($v['reservation_id'])?Reservation::lockForUpdate()->findOrFail($v['reservation_id']):null;$o=RestaurantOrder::lockForUpdate()->findOrFail($order->id);if($o->status!=='Open')Hotel::fail('Order is already settled.');if($v['settlement']==='Room'){if(!$r||$r->status!=='Checked-in')Hotel::fail('Room posting requires an active stay.');FolioCharge::create(['reservation_id'=>$r->id,'restaurant_order_id'=>$o->id,'description'=>'Restaurant '.$o->code,'amount'=>$o->amount]);}else {if($v['cash_received']<$o->amount)Hotel::fail('Cash received is insufficient.');Payment::create(['restaurant_order_id'=>$o->id,'receipt'=>'RCPT-'.strtoupper(bin2hex(random_bytes(6))),'amount'=>$o->amount,'method'=>'Cash','idempotency_key'=>$v['idempotency_key'],'posting_location'=>'Restaurant','created_by'=>$q->user()->id]);}$o->update(['status'=>'Settled','settlement'=>$v['settlement'],'reservation_id'=>$r?->id,'settled_at'=>now()]);if($o->dining_table_id)\App\Models\DiningTable::whereKey($o->dining_table_id)->update(['status'=>'Available']);Hotel::audit('order.settled',$o->code);return ['order'=>$o,'change'=>$v['settlement']==='Cash'?round($v['cash_received']-$o->amount,2):0];});}
 public function extraCharge(Request $q,Reservation $reservation){\App\Services\BusinessDate::assertOpen('Hotel');\App\Services\BusinessDate::assertNoCheckout($reservation->id);$v=$q->validate(['description'=>'required|string|max:255','amount'=>'required|numeric|min:0.01|max:999999']);return DB::transaction(function()use($reservation,$v){$r=Reservation::lockForUpdate()->findOrFail($reservation->id);if($r->status!=='Checked-in')Hotel::fail('Additional charges require an active stay.');$c=$r->charges()->create($v);Hotel::audit('charge.posted',$r->code);return $c;});}
 public function report(Request $q){$date=$q->validate(['date'=>'sometimes|date'])['date']??today()->toDateString();$payments=Payment::whereDate('created_at',$date)->when($q->user()->role==='frontdesk',fn($b)=>$b->whereNotNull('reservation_id'))->get();if($q->user()->role==='restaurant')return ['date'=>$date,'collections'=>$payments->whereNotNull('restaurant_order_id')->where('kind','Payment')->sum('amount'),'orders'=>RestaurantOrder::with('items')->whereDate('created_at',$date)->get(),'room_charges'=>RestaurantOrder::whereDate('settled_at',$date)->where('settlement','Room')->sum('amount')];return ['date'=>$date,'booking_amounts'=>Reservation::whereDate('created_at',$date)->sum('amount'),'additional_charges'=>FolioCharge::whereDate('created_at',$date)->sum('amount'),'restaurant_cash_bills'=>RestaurantOrder::where('settlement','Cash')->whereDate('settled_at',$date)->sum('amount'),'collections'=>$payments->where('kind','Payment')->sum('amount'),'refunds'=>$payments->where('kind','Refund')->sum('amount'),'payments'=>$payments,'arrivals'=>Reservation::with('guest','room')->whereDate('arrival',$date)->get(),'departures'=>Reservation::with('guest','room')->whereDate('departure',$date)->get(),'outstanding'=>Reservation::whereIn('status',['Confirmed','Checked-in'])->get()->map(fn($r)=>['id'=>$r->id,'code'=>$r->code,'balance'=>Hotel::folio($r)['balance']])->filter(fn($r)=>abs($r['balance'])>.005)->values()];}
 public function dashboard(){return ['guests'=>Guest::count(),'rooms'=>Room::count(),'in_house'=>Reservation::where('status','Checked-in')->count(),'open_orders'=>RestaurantOrder::where('status','Open')->count(),'arrivals'=>Reservation::whereDate('arrival',today())->count(),'collections'=>Payment::whereDate('created_at',today())->where('kind','Payment')->sum('amount')];}
}
